const globals=async(client)=>{
  const roles=await client.query("SELECT rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolbypassrls,rolconnlimit,rolvaliduntil::text,rolconfig FROM pg_roles WHERE rolname NOT LIKE 'pg_%' AND rolname<>'relay_pgsl' ORDER BY rolname");
  if(roles.rows.length!==1||roles.rows[0].rolname!=='iegoadmin')throw new Error('unhandled cluster roles');
  const databases=await client.query("SELECT datname,pg_get_userbyid(datdba) AS owner,encoding,datcollate,datctype,datlocprovider,daticulocale FROM pg_database WHERE NOT datistemplate ORDER BY datname");
  if(databases.rows.length!==2||databases.rows[0].datname!=='pgsl_prod'||databases.rows[1].datname!=='postgres')throw new Error('unhandled cluster databases');
  const settings=await client.query("SELECT coalesce(d.datname,'*') AS database,coalesce(r.rolname,'*') AS role,s.setconfig FROM pg_db_role_setting s LEFT JOIN pg_database d ON d.oid=s.setdatabase LEFT JOIN pg_roles r ON r.oid=s.setrole ORDER BY 1,2");
  const memberships=await client.query("SELECT parent.rolname AS role,child.rolname AS member,grantor.rolname AS grantor,m.admin_option,m.inherit_option,m.set_option FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid JOIN pg_roles child ON child.oid=m.member JOIN pg_roles grantor ON grantor.oid=m.grantor WHERE parent.rolname NOT LIKE 'pg_%' OR child.rolname NOT LIKE 'pg_%' ORDER BY 1,2,3");
  return JSON.stringify({roles:roles.rows,databases:databases.rows,settings:settings.rows,memberships:memberships.rows});
};
const verifyDefaultDatabase=async(url)=>{
  const value=new URL(url);value.pathname='/postgres';
  const client=new Client({connectionString:value.href,application_name:'pgsl-copy-default-db-check',connectionTimeoutMillis:15000});
  try{await client.connect();await client.query('BEGIN READ ONLY');
    const r=await client.query("SELECT (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%' AND c.relkind IN ('r','p','m','v','S','f'))::int AS relations,(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_%')::int AS routines,(SELECT count(*) FROM pg_namespace WHERE nspname NOT IN ('public','pg_catalog','information_schema') AND nspname NOT LIKE 'pg_toast%' AND nspname NOT LIKE 'pg_temp_%')::int AS schemas,(SELECT count(*) FROM pg_extension WHERE extname<>'plpgsql')::int AS extensions,(SELECT count(*) FROM pg_largeobject_metadata)::int AS large_objects");
    if(!Object.values(r.rows[0]).every(value=>Number(value)===0))throw new Error('default postgres database contains user objects');
    const access=await databaseAccessFingerprint(client);
    await client.query('ROLLBACK');return access;
  }finally{await client.end();}
};
